class Solution { public ListNode removeZeroSumSublists(ListNode head){ListNode dummy=new ListNode(0,head);Map<Integer,ListNode> last=new HashMap<>();int prefix=0;for(ListNode node=dummy;node!=null;node=node.next){prefix+=node.val;last.put(prefix,node);}prefix=0;for(ListNode node=dummy;node!=null;node=node.next){prefix+=node.val;node.next=last.get(prefix).next;}return dummy.next;} }
